28: func (c *Client) imageModelSettings(model string, defaultUpstream string, defaultEffort string) (string, string) {
29: 	_, baseModel := protocol.SplitImageModel(model)
30: 	if baseModel == "" {
31: 		return "auto", ""
32: 	}
33: 	var upstreamModel string
34: 	switch baseModel {
35: 	case "gpt-image-2":
36: 		// gpt-image-2 是「通用出图」入口：上游模型由配置决定（默认 auto），
37: 		// 这样用户可以用 default_upstream_model_name 切换底层模型。
38: 		//
39: 		// 回退值用 auto 而不是 gpt-5-5：后者已从上游模型列表消失，
40: 		// 继续用它会让这条链路指向不存在的模型。
41: 		if defaultUpstream == "" {
42: 			defaultUpstream = "auto"
43: 		}
44: 		upstreamModel = defaultUpstream
45: 	default:
46: 		// codex 系列不会走到这里（StreamImage 已在入口分流到 /codex/responses），
47: 		// 但 IsSupportedImageModel 兜住它，保证即使被误调用也透传模型名而不是 "auto"。
48: 		//
49: 		// 2.5/2.6 系列（gpt-image-2.5 / -flare / -sunburst、gpt-image-2.6 / -flare / -sunburst）：
50: 		// 模型名本身就是上游 slug，直接透传。实测 2.5 的三个名字作为
51: 		// upstream_model 传给 /f/conversation 能正常出图（三者字节数各异，
52: 		// 确认是不同模型）；2.6 系列按同一规则透传。
53: 		// 不要走 defaultUpstream 映射 —— 那会把它们全变成同一个模型，退化。
54: 		if protocol.IsSupportedImageModel(baseModel) {
55: 			upstreamModel = baseModel
56: 		} else {
57: 			return "auto", ""
58: 		}
59: 	}
