38: // 2.6 系列同样必须把模型名原样透传给上游，不能被 defaultUpstream 吃掉。
39: func TestImageModelSettings26SeriesPassThrough(t *testing.T) {
40: 	c := &Client{}
41: 	for _, model := range []string{
42: 		"gpt-image-2.6",
43: 		"gpt-image-2.6-flare",
44: 		"gpt-image-2.6-sunburst",
45: 	} {
46: 		upstream, _ := c.imageModelSettings(model, "gpt-5-6", "auto")
47: 		if upstream != model {
48: 			t.Errorf("%q -> upstream %q, want pass-through %q", model, upstream, model)
49: 		}

